using System.Security.Cryptography; using ControlGastos.Api.Services; using ControlGastos.Core.DTOs; using ControlGastos.Core.Entities; using ControlGastos.Core.Interfaces; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.Extensions.Options;
namespace ControlGastos.Api.Controllers;
[ApiController][Authorize][Route("api/telegram")]
public sealed class TelegramController(IUsuarioTelegramRepository usuarios,IVinculacionTelegramRepository tokens,IUsuarioActualService actual,IOptions<TelegramOptions> options):ControllerBase {
 [HttpGet("estado")] public async Task<ActionResult<ApiResponse<TelegramEstado_DTO>>> Estado(CancellationToken ct){var x=await usuarios.ObtenerAsync(actual.ObtenerIdUsuario(),ct);return Ok(new ApiResponse<TelegramEstado_DTO>{IsOk=true,Message="Estado de Telegram obtenido correctamente.",Data=new TelegramEstado_DTO{Vinculado=x is not null,Username=x?.NombreUsuarioTelegram}});}
 [HttpPost("vinculacion")] public async Task<ActionResult<ApiResponse<TelegramVinculacion_DTO>>> Vinculacion(CancellationToken ct){if(await usuarios.ObtenerAsync(actual.ObtenerIdUsuario(),ct) is not null)return Conflict(new ApiResponse<object>{IsOk=false,Message="Telegram ya está vinculado."});var token=Convert.ToHexString(RandomNumberGenerator.GetBytes(32));await tokens.CrearAsync(new VinculacionTelegram{IdUsuario=actual.ObtenerIdUsuario(),CodigoToken=token,FechaExpiracion=DateTimeOffset.UtcNow.AddMinutes(10),EstaUsado=false,FechaRegistro=DateTimeOffset.UtcNow},ct);return Ok(new ApiResponse<TelegramVinculacion_DTO>{IsOk=true,Message="Enlace de vinculación generado.",Data=new TelegramVinculacion_DTO{BotUsername=options.Value.BotUsername,Token=token,ExpiraEnSegundos=600}});}
 [HttpDelete("vinculacion")] public async Task<ActionResult<ApiResponse<object>>> Desvincular(CancellationToken ct){await usuarios.DesvincularAsync(actual.ObtenerIdUsuario(),ct);return Ok(new ApiResponse<object>{IsOk=true,Message="Telegram desvinculado correctamente."});}
}
